import React, { useState } from 'react'; // 引入 useState
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, Calendar, User, MapPin, Clock, MoreVertical, Search, Layers } from 'lucide-react';
import './MeetingRoom.css';

const MeetingRoom = () => {
  const navigate = useNavigate();
  // 状态：是否处于搜索模式
  const [isSearching, setIsSearching] = useState(false);

  // 处理返回逻辑：如果在搜索中，点击返回则退出搜索；否则返回首页
  const handleBack = () => {
    if (isSearching) {
      setIsSearching(false);
    } else {
      navigate('/');
    }
  };

  return (
    <div className="meeting-room-container">
      {/* 1. 固定顶部导航栏 (Back 功能依然有效) */}
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">{isSearching ? "Search Room" : "Meeting Room"}</span>
      </nav>

      {/* 2. 独立滚动区域 */}
      <div className="scrollable-area">
        {!isSearching ? (
          /* --- 原有的列表视图 (被隐藏的部分) --- */
          <div className="content-padding">
            <div className="tabs-header">
              <button className="tab active">List All</button>
              <button className="tab">Today</button>
              <button className="tab">Week</button>
            </div>

            <div className="summary-banner">
              <div className="summary-icon">
                <Calendar size={22} color="#1976d2" strokeWidth={2} />
              </div>
              <div className="summary-info">
                <h2 style={{ fontSize: "13pt", fontWeight: "bold", margin: 0 }}>
                  1 Meeting Upcoming
                </h2>
                <p style={{ fontSize: "10pt", fontWeight: "bold", margin: "2px 0 0", color: "#000000" }}>
                  22 Jan, Thursday
                </p>
              </div>
            </div>

            <div className="meeting-list">
              <div className="details-card">
                <div className="card-top">
                  <h3 style={{margin: 0, fontSize: '15px'}}>UAT Briefing</h3>
                  <button className="more-options">
                    <MoreVertical size={20} color="#999" />
                  </button>
                </div>
                
                <div className="info-rows">
                  <div className="row">
                    <span className="icon"><User size={18} strokeWidth={2} /></span>
                    <span className="text">ALAN TAN WAI LOON</span>
                  </div>
                  <div className="row">
                    <span className="icon"><MapPin size={18} strokeWidth={2} /></span>
                    <span className="text">Idea Lab 6</span>
                  </div>
                  <div className="row">
                    <span className="icon"><Calendar size={18} strokeWidth={2} /></span>
                    <span className="text">2026-01-22</span>
                  </div>
                  <div className="row">
                    <span className="icon"><Clock size={18} strokeWidth={2} /></span>
                    <span className="text">12:00 PM - 12:30 PM</span>
                  </div>
                </div>

                <div className="card-bottom">
                  <div className="attendee-count">
                    <div className="icon-circle">
                      <User size={14} strokeWidth={2.5} />
                    </div>
                    <span className="attendee-number">1</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ) : (
          /* --- 新的搜索视图 (点击 Search Room 后显示) --- */
          <div className="search-view-container">
            {/* 搜索输入框 */}
            <div className="search-bar-card">
              <input type="text" placeholder="Search room name..." className="search-input" />
              <Search size={20} color="#999" className="search-magnifier" />
            </div>

            {/* 10 个搜索结果 Box */}
            <div className="search-results-list">
              {[...Array(10)].map((_, index) => (
                <div key={index} className="room-sub-box">
                  {/* 左边 30% 正方形区域 */}
                  <div className="room-box-left"></div>
                  {/* 右边文字信息区域 */}
                  <div className="room-box-right">
                    <h4 className="room-title">Idea Lab 5</h4>
                    <div className="room-details">
                      <div className="detail-item">
                        <User size={14} color="#666" /> <span>8 seats</span>
                      </div>
                      <div className="detail-item">
                        <Layers size={14} color="#666" /> <span>Level 19</span>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* 3. 固定在底部的 Search Room 按钮 (进入搜索模式后隐藏) */}
      {!isSearching && (
        <div className="search-footer">
          <button className="search-room-btn" onClick={() => setIsSearching(true)}>
            <Search size={18} style={{marginRight: '8px'}} />
            Search Room
          </button>
        </div>
      )}
    </div>
  );
};

export default MeetingRoom;
